std::vector<std::unique_ptr<ChooserContextBase::Object>> GetGrantedObjects(const GURL& requesting_origin, const GURL& embedding_origin) {
    std::vector<std::unique_ptr<ChooserContextBase::Object>> results;

    // Check if the provided origins are valid
    if (!requesting_origin.is_valid() || !embedding_origin.is_valid()) {
        return results;
    }

    // Check if permission can be granted for the requested origins
    if (!IsPermissionGranted(requesting_origin, embedding_origin)) {
        return results;
    }

    // Retrieve the website settings and extract the object list
    std::vector<std::unique_ptr<ChooserContextBase::Object>> objects = GetWebsiteSettings(requesting_origin, embedding_origin);

    // Validate and add each object to the results vector
    for (const auto& object : objects) {
        if (object && IsObjectValid(*object)) {
            results.push_back(std::make_unique<ChooserContextBase::Object>(*object));
        }
    }

    return results;
}
